<script setup lang="ts">
import {ref,reactive,onMounted,computed} from 'vue'
import {Mail,Copy,Plus,RefreshCw,Heart,Check} from 'lucide-vue-next'
import {INVITATION_EMAIL_ENABLED} from '../lib/config'
import {appUrl} from '../lib/urls'
import {db,fail,friendly} from '../lib/supabase'
interface Pass {id:string;email:string;display_name:string;personal_message:string;max_guests:number;expires_at:string;revoked:boolean;claimed_by:string|null;sent_at:string|null;delivery_error:string|null}
const form=reactive({email:'',name:'',message:'Nos haría muchísima ilusión compartir este día contigo.',limit:1})
const passes=ref<Pass[]>([]),busy=ref(false),error=ref(''),notice=ref(''),sendOnCreate=ref(INVITATION_EMAIL_ENABLED),latest=ref<{id:string;token:string;display_name:string;email:string}|null>(null),revokeId=ref('')
const link=computed(()=>latest.value?appUrl+'#invite='+latest.value.token:'')
async function load(){const {data,error:e}=await db.from('wedding_guest_passes').select('id,email,display_name,personal_message,max_guests,expires_at,revoked,claimed_by,sent_at,delivery_error').order('created_at',{ascending:false});fail(e);passes.value=data??[]}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=friendly(e)}finally{busy.value=false}}
async function send(){if(!latest.value)return;const {data,error:e}=await db.functions.invoke('send-wedding-invitation',{body:{pass_id:latest.value.id,invite_token:latest.value.token}});if(e){let detail='No se ha enviado el correo. Puedes copiar el enlace y compartirlo personalmente.';try{const payload=await (e as any).context?.json();if(payload?.error)detail=payload.error}catch{}throw new Error(detail)}if(data?.error)throw new Error(data.error);notice.value='El proveedor ha aceptado el correo de invitación. La entrega puede tardar unos minutos.'}
async function create(){await action(async()=>{const {data,error:e}=await db.rpc('wedding_manage_guest_pass',{operation:'create',guest_email:form.email.trim(),guest_name:form.name.trim(),guest_message:form.message,guest_limit:form.limit});fail(e);latest.value=data;form.email='';form.name='';notice.value='Invitación creada. Ya puedes copiar su enlace personal.';await load();if(sendOnCreate.value){try{await send()}finally{await load()}}})}
async function renew(p:Pass){await action(async()=>{const {data,error:e}=await db.rpc('wedding_manage_guest_pass',{operation:'renew',pass_id:p.id});fail(e);latest.value=data;notice.value='Nuevo enlace preparado. El enlace anterior deja de funcionar.';await load()})}
async function revoke(p:Pass){await action(async()=>{const {error:e}=await db.rpc('wedding_manage_guest_pass',{operation:'revoke',pass_id:p.id});fail(e);if(latest.value?.id===p.id)latest.value=null;revokeId.value='';await load();notice.value='Enlace desactivado. Puedes generar uno nuevo cuando quieras.'})}
async function copy(){await action(async()=>{await navigator.clipboard.writeText(link.value);notice.value='Enlace copiado. Compártelo únicamente con la persona invitada.'})}
function state(p:Pass){return p.claimed_by?'Activada':p.revoked?'Desactivada':Date.parse(p.expires_at)<Date.now()?'Caducada':p.sent_at?'Correo enviado':'Pendiente de enviar'}
onMounted(()=>{void action(load)})
</script>
<template><section class="invite-manager"><div class="invite-manager-title"><Mail/><div><h2>Una invitación con su nombre</h2><p>Prepara su postal. Después elegirá su contraseña, alias y preferencias.</p></div></div><form class="form-grid" @submit.prevent="create"><label>Nombre para la postal<input v-model="form.name" required minlength="2" maxlength="100" placeholder="María y familia"/></label><label>Correo de la persona titular<input v-model="form.email" type="email" required maxlength="254" placeholder="nombre@correo.com"/></label><label>Cupo total<select v-model.number="form.limit"><option v-for="n in 10" :key="n" :value="n">{{n}} {{n===1?'persona':'personas'}}</option></select></label><label class="full-width">Una dedicatoria<textarea v-model="form.message" maxlength="1200" rows="3"/></label><label v-if="INVITATION_EMAIL_ENABLED" class="check full-width"><input v-model="sendOnCreate" type="checkbox"/>Enviar la postal por correo al crear la invitación</label><p v-if="!INVITATION_EMAIL_ENABLED" class="notice full-width">El correo automático está pendiente de activar. Puedes crear el enlace y compartir la postal personalmente.</p><button class="btn" :disabled="busy"><Plus :size="17"/>{{busy?'Preparando…':sendOnCreate?'Crear y enviar invitación':'Crear enlace personal'}}</button></form><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success" role="status">{{notice}}</p><div v-if="latest" class="personal-link"><span class="eyebrow">LISTA PARA {{latest.display_name}}</span><label>Enlace personal<input :value="link" readonly @focus="($event.target as HTMLInputElement).select()"/></label><div class="invite-link-actions"><button class="btn secondary" @click="copy" :disabled="busy"><Copy :size="16"/> Copiar enlace</button><button v-if="INVITATION_EMAIL_ENABLED" class="btn" @click="action(async()=>{try{await send()}finally{await load()}})" :disabled="busy"><Mail :size="16"/> Enviar por correo</button></div><small>Válido durante 90 días y vinculado a su correo. Guarda el enlace antes de salir de esta pantalla.</small></div><h3 class="invite-list-title">Invitaciones preparadas <span>{{passes.length}}</span></h3><p v-if="!passes.length" class="empty-state">La primera postal está por escribir.</p><article v-for="p in passes" :key="p.id" class="prepared-invite"><Heart :size="20"/><div><b>{{p.display_name}}</b><p>{{p.email}} · {{p.max_guests}} {{p.max_guests===1?'persona':'personas'}}</p><span class="badge"><Check v-if="p.claimed_by" :size="12"/>{{state(p)}}</span><small v-if="!p.claimed_by">Caduca el {{new Date(p.expires_at).toLocaleDateString('es-ES')}}</small><p v-if="p.delivery_error" class="small error">{{p.delivery_error}}</p></div><div v-if="!p.claimed_by" class="prepared-actions"><button class="text-link" :disabled="busy" @click="renew(p)"><RefreshCw :size="14"/> Generar nuevo enlace</button><button v-if="!p.revoked&&revokeId!==p.id" class="text-link" @click="revokeId=p.id">Desactivar enlace</button><template v-if="revokeId===p.id"><span class="small">El enlace dejará de abrir la postal.</span><button class="text-link" :disabled="busy" @click="revoke(p)">Sí, desactivar</button><button class="text-link" @click="revokeId=''">Cancelar</button></template></div></article></section></template>
